// protoc-gen-orm-rust emits Rust helpers for the Get contracts generated by
// protoc-gen-orm-service. The descriptors are the authority on index layout.
package main

import (
	"fmt"
	"io"
	"os"
	"path"
	"sort"
	"strings"

	"github.com/ettle/strcase"
	"github.com/protobuf-orm/protobuf-orm/ormpb"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/reflect/protodesc"
	r "google.golang.org/protobuf/reflect/protoreflect"
	"google.golang.org/protobuf/types/descriptorpb"
	"google.golang.org/protobuf/types/pluginpb"
)

func main() {
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		fail(err)
	}
	req := new(pluginpb.CodeGeneratorRequest)
	if err := proto.Unmarshal(data, req); err != nil {
		fail(err)
	}
	resp := &pluginpb.CodeGeneratorResponse{
		SupportedFeatures: proto.Uint64(uint64(pluginpb.CodeGeneratorResponse_FEATURE_PROTO3_OPTIONAL | pluginpb.CodeGeneratorResponse_FEATURE_SUPPORTS_EDITIONS)),
		MinimumEdition:    proto.Int32(int32(descriptorpb.Edition_EDITION_2023)),
		MaximumEdition:    proto.Int32(int32(descriptorpb.Edition_EDITION_2023)),
	}
	if err := generate(req, resp); err != nil {
		resp.File = nil
		resp.Error = proto.String(err.Error())
	}
	data, err = proto.Marshal(resp)
	if err != nil {
		fail(err)
	}
	if _, err = os.Stdout.Write(data); err != nil {
		fail(err)
	}
}

func fail(err error) { fmt.Fprintln(os.Stderr, err); os.Exit(1) }

func generate(req *pluginpb.CodeGeneratorRequest, resp *pluginpb.CodeGeneratorResponse) error {
	if req.GetParameter() != "" && req.GetParameter() != "storage_model" {
		return fmt.Errorf("unexpected plugin parameter %q", req.GetParameter())
	}
	files, err := protodesc.NewFiles(&descriptorpb.FileDescriptorSet{File: req.ProtoFile})
	if err != nil {
		return err
	}
	names := append([]string(nil), req.FileToGenerate...)
	sort.Strings(names)
	if req.GetParameter() == "storage_model" {
		return storageModel(files, names, resp)
	}
	for _, name := range names {
		f, err := files.FindFileByPath(name)
		if err != nil {
			return err
		}
		var body strings.Builder
		for i := 0; i < f.Services().Len(); i++ {
			svc := f.Services().Get(i)
			get := svc.Methods().ByName("Get")
			if get == nil || !proto.HasExtension(get.Output().Options(), ormpb.E_Message) {
				continue
			}
			if string(svc.Name()) != string(get.Output().Name())+"Service" {
				continue
			}
			if err := entity(&body, svc, get); err != nil {
				return fmt.Errorf("%s: %w", svc.FullName(), err)
			}
		}
		if body.Len() != 0 {
			output := strings.TrimSuffix(name, path.Ext(name)) + ".orm.rs"
			resp.File = append(resp.File, &pluginpb.CodeGeneratorResponse_File{Name: proto.String(output), Content: proto.String("// @generated by protoc-gen-orm-rust.\n" + body.String())})
		}
	}
	return nil
}

// Buffa emits top-level protobuf messages at the package module root.
func messageType(m r.MessageDescriptor) (string, error) {
	if _, nested := m.Parent().(r.MessageDescriptor); nested {
		return "", fmt.Errorf("nested key type %s is unsupported", m.FullName())
	}
	pkg := string(m.ParentFile().Package())
	if pkg == "google.protobuf" {
		return "::buffa_types::google::protobuf::" + string(m.Name()), nil
	}
	return module("crate::proto", pkg) + "::" + string(m.Name()), nil
}
func module(root, pkg string) string {
	if pkg == "" {
		return root
	}
	parts := strings.Split(pkg, ".")
	for i, part := range parts {
		parts[i] = rustIdent(part)
	}
	return root + "::" + strings.Join(parts, "::")
}

// Buffa escapes path-only keywords with a suffix, other keywords with r#.
func rustIdent(s string) string {
	switch s {
	case "self", "super", "Self", "crate":
		return s + "_"
	case "as", "break", "const", "continue", "else", "enum", "extern", "false", "fn", "for", "if", "impl", "in", "let", "loop", "match", "mod", "move", "mut", "pub", "ref", "return", "static", "struct", "trait", "true", "type", "unsafe", "use", "where", "while", "async", "await", "dyn", "abstract", "become", "box", "do", "final", "macro", "override", "priv", "typeof", "unsized", "virtual", "yield", "try", "gen":
		return "r#" + s
	}
	return s
}

func keyType(f r.FieldDescriptor) (string, error) {
	if f.IsList() || f.IsMap() {
		return "", fmt.Errorf("collection key %s is unsupported", f.FullName())
	}
	switch f.Kind() {
	case r.MessageKind:
		return messageType(f.Message())
	case r.BoolKind:
		return "bool", nil
	case r.StringKind:
		return "String", nil
	case r.BytesKind:
		return "Vec<u8>", nil
	case r.Int32Kind, r.Sint32Kind, r.Sfixed32Kind:
		return "i32", nil
	case r.Uint32Kind, r.Fixed32Kind:
		return "u32", nil
	case r.Int64Kind, r.Sint64Kind, r.Sfixed64Kind:
		return "i64", nil
	case r.Uint64Kind, r.Fixed64Kind:
		return "u64", nil
	case r.FloatKind:
		return "f32", nil
	case r.DoubleKind:
		return "f64", nil
	}
	return "", fmt.Errorf("unsupported key %s (%s)", f.FullName(), f.Kind())
}

func entity(out *strings.Builder, svc r.ServiceDescriptor, get r.MethodDescriptor) error {
	field := get.Input().Fields().ByName("ref")
	if field == nil || field.Message() == nil {
		return fmt.Errorf("Get request requires a ref message")
	}
	ref := field.Message()
	key := ref.Oneofs().ByName("key")
	if key == nil {
		return fmt.Errorf("%s requires a key oneof", ref.FullName())
	}
	refType, err := messageType(ref)
	if err != nil {
		return err
	}
	request, err := messageType(get.Input())
	if err != nil {
		return err
	}
	keyEnum := module("crate::proto", string(ref.ParentFile().Package())) + "::" + strcase.ToSnake(string(ref.Name())) + "::Key"
	fmt.Fprintf(out, "\nimpl %s {\n", refType)
	for i := 0; i < key.Fields().Len(); i++ {
		f := key.Fields().Get(i)
		typ, err := keyType(f)
		if err != nil {
			return err
		}
		args := []string{"value: " + typ}
		value := "value"
		if m := f.Message(); m != nil {
			if strings.HasPrefix(string(m.Name()), string(ref.Name())+"By") {
				var fields []string
				args = nil
				for j := 0; j < m.Fields().Len(); j++ {
					part := m.Fields().Get(j)
					t, err := keyType(part)
					if err != nil {
						return err
					}
					ident := rustIdent(strcase.ToSnake(string(part.Name())))
					args = append(args, ident+": "+t)
					fields = append(fields, ident+": "+ident+".into(),")
				}
				value = fmt.Sprintf("%s {\n                %s\n                ..Default::default()\n            }", typ, strings.Join(fields, "\n                "))
			}
			value = "Box::new(" + value + ")"
		}
		fmt.Fprintf(out, "    pub fn by_%s(%s) -> Self {\n        Self { key: Some(%s::%s(%s)), ..Default::default() }\n    }\n", strcase.ToSnake(string(f.Name())), strings.Join(args, ", "), keyEnum, strcase.ToPascal(string(f.Name())), value)
	}
	fmt.Fprintf(out, "    pub fn pick(self) -> %s {\n        %s { r#ref: self.into(), ..Default::default() }\n    }\n}\n", request, request)
	if sel := get.Input().Fields().ByName("select"); sel != nil && sel.Message() != nil {
		typ, err := messageType(sel.Message())
		if err != nil {
			return err
		}
		fmt.Fprintf(out, "\nimpl %s {\n    pub fn with_select(mut self, selection: %s) -> Self {\n        self.select = selection.into();\n        self\n    }\n}\n", request, typ)
	}
	service := module("crate::services", string(svc.ParentFile().Package())) + "::" + string(svc.Name())
	fmt.Fprintf(out, "\npub fn register_%s<T: %s>(router: ::connectrpc::Router, service: ::std::sync::Arc<T>) -> ::connectrpc::Router {\n    %sExt::register(service, router)\n}\n", strcase.ToSnake(string(svc.Name())), service, service)
	return nil
}
